"""PlatformIO pre-build script: embed every web/*.html into src/web_pages.h.

Each page becomes a PROGMEM raw string literal named PAGE_<BASENAME> (upper
case), so the firmware needs no filesystem image. The header is rewritten
only when its content changes, to keep incremental builds fast.
"""
import glob
import os

Import("env")  # noqa: F821  (provided by PlatformIO)

project_dir = env["PROJECT_DIR"]
src_paths = sorted(glob.glob(os.path.join(project_dir, "web", "*.html")))
dst_path = os.path.join(project_dir, "src", "web_pages.h")

DELIM = "html"
parts = [
    "// Generated by scripts/embed_web.py from web/*.html. Do not edit.\n",
    "#pragma once\n",
    "#include <pgmspace.h>\n",
]
for src_path in src_paths:
    with open(src_path, encoding="utf-8") as f:
        html = f.read()
    if f'){DELIM}"' in html:
        raise SystemExit(f"embed_web.py: {os.path.basename(src_path)} must not contain '){DELIM}\"'")
    name = os.path.splitext(os.path.basename(src_path))[0].upper()
    parts.append(f'static const char PAGE_{name}[] PROGMEM = R"{DELIM}({html}){DELIM}";\n')
out = "".join(parts)

existing = None
if os.path.exists(dst_path):
    with open(dst_path, encoding="utf-8") as f:
        existing = f.read()

if existing != out:
    with open(dst_path, "w", encoding="utf-8") as f:
        f.write(out)
    print(f"embed_web.py: regenerated {os.path.relpath(dst_path, project_dir)}")
